// Verus program: rotate a non-empty list left by n (0 < n < len)
//
// The result is list[n..] followed by list[..n], preserving relative order.

use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        // Exact left-rotation spec:
        forall|i: int|
            0 <= i < list.len() ==> (
                new_list[i] == if i < (list.len() - n) as int {
                    list[(i + n as int) as int]
                } else {
                    list[(i - (list.len() - n) as int) as int]
                }
            ),
{
    let len = list.len();
    let mut out: Vec<i32> = Vec::new();

    // Build out = list[n..len]
    let mut i: usize = n;
    while i < len
        invariant
            list.len() == len,
            0 < n,
            n < len,
            n <= i <= len,
            out.len() == i - n,
            forall|k: int|
                0 <= k < out.len() ==> out[k] == list[(n as int + k) as int],
    {
        out.push(list[i]);
        i += 1;
    }

    // Append list[0..n]
    let base_len = out.len(); // == len - n
    let mut j: usize = 0;
    while j < n
        invariant
            list.len() == len,
            0 < n,
            n < len,
            j <= n,
            out.len() == base_len + j,
            base_len == len - n,
            // First segment still matches list[n..]
            forall|k: int|
                0 <= k < base_len ==> out[k] == list[(n as int + k) as int],
            // Appended segment matches list[0..j)
            forall|k: int|
                0 <= k < j ==> out[(base_len as int + k)] == list[k],
    {
        out.push(list[j]);
        j += 1;
    }

    // out now has length len and equals list[n..] ++ list[..n]
    out
}

} // verus!